import { readFile, writeFile, mkdir } from "node:fs/promises";
import { resolve } from "node:path";
import { captureProductionSchema, createProductionClone, hash } from "../../../../supabase/rls-tests/helpers/productionSchemaClone";
import { applyDocumentGuards, documentGuardSnapshotContextRefusal } from "../../../../supabase/rls-tests/helpers/documentGuardApplication";

const output = resolve(import.meta.dir, "missing-" + new Date().toISOString().replaceAll(/[^0-9T]/g, ""));
await mkdir(output);
const catalogOids = ["826", "1214", "1247", "1249", "1255", "1259", "2604", "2606", "2608", "2610", "2617", "2620", "3256"];
let clone: Awaited<ReturnType<typeof createProductionClone>> | undefined;
const receipt: Record<string, unknown> = { output, scope: "Read-only public/private hosted schema capture, no production rows; unchanged guard installation on one new owned loopback clone170006 only", normalDrop: false, migrationSubmitted: false };
const polls: unknown[] = [];
try {
  console.log(JSON.stringify({ phase: "READ_ONLY_SCHEMA_CAPTURE" }));
  const capture = await captureProductionSchema();
  receipt.productionSchemaSha256 = hash(capture.schema);
  receipt.productionCatalogSha256 = hash(capture.catalog);
  receipt.captureAtUtc = new Date().toISOString();
  clone = await createProductionClone(capture);
  receipt.clone = clone.name;
  receipt.zeroDataTables = clone.tableCount;
  receipt.managedPrerequisitesSha256 = clone.prerequisites;
  let ready = false;
  for (let i = 0; i < 18; i++) {
    const result = await clone.sql.begin(async tx => {
      await tx`set transaction read only`;
      return tx`select clock_timestamp()::text as at,s.relid::text as oid,s.last_autoanalyze::text,s.autoanalyze_count::text from pg_catalog.pg_stat_all_tables s where s.schemaname='pg_catalog' and s.relid::text=any(${"{" + catalogOids.join(",") + "}"}::pg_catalog.text[]) order by s.relid`;
    });
    polls.push(result);
    if (result.length === catalogOids.length && result.every((r: { autoanalyze_count: string }) => Number(r.autoanalyze_count) > 0)) { ready = true; break; }
    console.log(JSON.stringify({ phase: "WAIT_SETUP_AUTOANALYZE", attempt: i + 1, clone: clone.name, ready: result.filter((r: { autoanalyze_count: string }) => Number(r.autoanalyze_count) > 0).length, total: catalogOids.length }));
    await Bun.sleep(5000);
  }
  if (!ready) throw new Error("Setup autoanalyze precondition not observed within bounded90s; no migration submitted");
  await Bun.sleep(2000);
  receipt.setupCompleted = true;
  const sql = await readFile(resolve(import.meta.dir, "../../../../supabase/migrations/20261003075753_r01_document_publication_guards_forward.sql"), "utf8");
  receipt.migrationSourceSha256 = hash(sql);
  receipt.migrationSubmitted = true;
  const result = await applyDocumentGuards(clone, sql, "missing");
  receipt.application = result;
  if (result.admittedObjects.length !== 9 || !result.firstPreservation.unaffectedRawEqual || !result.secondPreservation.rawEqual || result.firstPreservation.maintenanceDeltas.length || result.secondPreservation.maintenanceDeltas.length) throw new Error("Strict unaffected raw/second apply equality not observed; no maintenance waiver accepted");
  receipt.contextRefusal = await documentGuardSnapshotContextRefusal(clone);
  receipt.complete = true;
} catch (error) {
  receipt.error = { message: error instanceof Error ? error.message : String(error), code: error !== null && typeof error === "object" && "code" in error ? String(error.code) : null, preservationDrift: error !== null && typeof error === "object" && "preservationDrift" in error ? error.preservationDrift : null };
  process.exitCode = 1;
} finally {
  try { if (clone) { await clone.close(); receipt.normalDrop = true; receipt.templatePreserved = clone.templatePreserved; } }
  catch (error) { receipt.cleanupError = error instanceof Error ? error.message : String(error); process.exitCode = 1; }
  await writeFile(resolve(output, "polls.json"), JSON.stringify(polls, null, 2));
  await writeFile(resolve(output, "receipt.json"), JSON.stringify(receipt, null, 2));
  console.log(JSON.stringify({ output, complete: receipt.complete ?? false, error: receipt.error ?? null, migrationSubmitted: receipt.migrationSubmitted, normalDrop: receipt.normalDrop, templatePreserved: receipt.templatePreserved ?? null, zeroDataTables: receipt.zeroDataTables ?? null, qualification: "Missing170006 only; no live DB migration, activation, test-safety source amendment or failure waiver" }));
}
